export async function ask(text: string, shown?: string) {
  if (!text.trim() || busy) return
  St.pushMsg({ role: 'user', text: shown || text })
  const id = St.pushMsg({ role: 'gr', thinking: true, blocks: [], steps: [] })
  busy = true; last = St.get().seen.last || {}
  try {
    const sf = F.safetyFirst(toEn(text)) /* the same fixed safety check runs first in both modes; the model never decides alone */
    const upgrade = async (r: F.R) => { /* the model check can make a fixed safety answer more urgent, never less */ if (!(mode === 'claude' && sample) || r.blocks.some((b: any) => b.kind === 'crisis' && ['danger', 'medical', 'risk'].includes(b.urgent))) return; const prev = [...St.get().chat].reverse().filter(m => m.role === 'user')[1]?.text || ''; const v = await safetyCheck(text, prev, new AbortController().signal); if (['suicide_plan', 'overdose', 'medical', 'suicide', 'emergency'].includes(v.risk) && !(['suicide', 'medical', 'emergency'].includes(v.risk) && r.blocks.some((b: any) => b.kind === 'crisis' || b.kind === 'emergency'))) { const c = safetyCard(v, text); if (c) respond(c, id) } }
    if (sf) { respond(sf, id); await upgrade(sf) }
    else if (F.mixedCrisis(toEn(text))) { const r = local(text); respond(r, id); await upgrade(r) } /* a crisis phrase with a task: crisis first, the task offered as a button */
    else if (mode === 'claude' && sample) await askClaude(text, id)
    else respond(local(text), id)
  } finally { busy = false; St.patchMsg(id, { thinking: false }); St.set(x => ({ seen: { ...x.seen, last: { ...last, opts: last.opts?.slice(0, 6) } } })) }
}

