/* A second, meaning-based safety check with Claude on every message, alongside the answer. The keyword check has already run;
   this catches what keywords miss. If it finds real risk, the answer is dropped and the fixed safety card is shown instead. */
const SAFETY_PROMPT = `You check one message sent to a bank's shopping and card assistant for immediate risk to a person. Reply with JSON only: {"risk": "...", "who": "self" | "other"}.
risk is one of: "none"; "suicide_plan" (a plan, method, time or goodbye); "suicide" (wants to die or self-harm, no plan stated); "overdose" (has taken too much medicine, or swallowed something harmful); "medical" (someone not breathing, unconscious, collapsed, choking, a seizure); "abuse" (being hurt or threatened by someone at home, or afraid of them); "coercion" (someone is pressuring or forcing them right now to pay, send money or hand over a card); "scam" (someone they met online, a caller, a texter or a person at the door is asking them for money, fees, gift cards, codes, their PIN or their card); "emergency" (an injury, heavy bleeding, a fire, an intruder, being followed, or a missing child).
Figures of speech ("dying to see", "this is killing me", "overdose of sunshine", "die laughing"), jokes, films, and ordinary requests are "none". Messages may be in English or Arabic (including Gulf dialect).`
async function safetyCheck(text: string, prev: string, signal: AbortSignal): Promise<{ risk: string; who: string }> {
  try {
    const t = sample.json ? await Promise.race([sample.json(`${SAFETY_PROMPT}\n\nEarlier message from the customer: ${JSON.stringify(prev.slice(0, 300))}\nMessage to check: ${JSON.stringify(text.slice(0, 600))}`, { modelTier: 'quick', signal, cache: false }), new Promise(r => setTimeout(() => r({ risk: 'none' }), 8000))]) : { risk: 'none' }
    return { risk: String((t as any)?.risk || 'none'), who: String((t as any)?.who || 'self') }
  } catch { return { risk: 'none', who: 'self' } }
}
function safetyCard(v: { risk: string; who: string }, text: string): F.R | null {
  const en = toEn(text).toLowerCase()
  switch (v.risk) {
    case 'suicide_plan': return F.crisis(`${en} tonight i have a plan`)
    case 'suicide': return v.who === 'other' ? F.safety('my son said he wants to kill himself') || F.crisis(en) : F.crisis(`${en} i want to die`)
    case 'overdose': return F.crisis(v.who === 'other' ? `my child swallowed too many pills ${en}` : `i took too many pills ${en}`)
    case 'medical': return F.medical(v.who === 'other' ? '' : 'i am ' + en)
    case 'emergency': return F.emergencyR(en) || F.emergencyR(v.who === 'other' ? `my child is missing ${en}` : `i need an ambulance ${en}`)
    case 'abuse': return F.safety("i'm not safe at home")
    case 'scam': return /\b(door|doorstep|knock\w*|courier|collect)\b|باب/.test(en + text) ? F.safety('a man at the door says I owe money and wants my card') : /\b(code|otp|passcode|pin)\b/.test(en) ? F.safetyScam('code') : /\b(link|email|text|sms)\b/.test(en) ? F.safetyScam('email') : /\b(job|task)\b/.test(en) ? F.safetyScam('job') : /\b(deposit|marketplace|seller)\b/.test(en) ? F.safetyScam('deposit') : /\b(online|instagram|facebook|dating|tinder|met|boyfriend|girlfriend|lover|snapchat|whatsapp|telegram|tiktok)\b/.test(en) ? F.safety('my new boyfriend from instagram wants me to send him money') : F.safetyScam('call')
    case 'coercion': return /\b(door|doorstep|courier|collect)\b|باب/.test(en + text) ? F.safety('a man at the door says I owe money and wants my card') : F.safety('someone is standing next to me telling me to send money')
    default: return null
  }
}
